import { createSlug } from "~/utils/slug";
import { createPath, createRoute } from "~/utils/slug";
import type { CourseMetadata, FolderItem, PageBuilderOptions, TopicEntry } from "./types";

function addDefaultTopic(entries: TopicEntry[], folder: FolderItem, heading?: string) {
  entries.push({
    name: folder.name,
    section: folder.name,
    folder,
    depth: 0,
    heading,
    mode: "default",
  });
}

export function listTopics(
  metadata: CourseMetadata,
  options: PageBuilderOptions = {},
): TopicEntry[] {
  if (options.singlePage) {
    return [];
  }

  const entries: TopicEntry[] = [];

  for (const folder of metadata) {
    if (options.tabs && folder.folders?.length && !options.makeHeading) {
      entries.push({
        name: folder.name,
        section: folder.name,
        folder,
        depth: 0,
        mode: "tabs",
      });
      continue;
    }

    if (options.makeHeading && folder.folders?.length) {
      folder.folders.forEach((sub, index) => {
        entries.push({
          name: sub.name,
          section: folder.name,
          folder: sub,
          depth: 0,
          heading: index === 0 ? folder.name : undefined,
          mode: "heading",
        });
      });
      continue;
    }

    addDefaultTopic(entries, folder);
  }

  if (options.heading && entries.length > 0) {
    entries[0].heading = options.heading;
  }

  return entries;
}

export function getTopicPathSegments(topic: Pick<TopicEntry, "mode" | "section" | "name">) {
  return topic.mode === "heading" ? [topic.section, topic.name] : [topic.name];
}

export function getTopicRouteKey(topic: Pick<TopicEntry, "mode" | "section" | "name">) {
  return createPath(...getTopicPathSegments(topic));
}

export function createTopicRoute(
  basePath: string,
  category: string,
  courseName: string,
  topic: TopicEntry,
) {
  return createRoute(basePath, category, courseName, ...getTopicPathSegments(topic));
}

/**
 * Route key -> TopicEntry. Heading-mode topics are keyed by both their
 * section and topic slugs so identically named topics in different sections
 * still resolve to the correct page.
 *
 * Duplicate-key safety: only the first topic for a given slug is kept,
 * matching `.find()`'s first-match behavior.
 */
export function buildTopicRouteMap(topics: TopicEntry[]): Map<string, TopicEntry> {
  const map = new Map<string, TopicEntry>();
  for (const topic of topics) {
    const routeKey = getTopicRouteKey(topic);
    if (!map.has(routeKey)) {
      map.set(routeKey, topic);
    }
  }
  return map;
}

/**
 * Supports previously published one-segment topic URLs as aliases after a
 * course switches its heading-mode topics to nested URLs.
 */
export function buildLegacyTopicSlugMap(topics: TopicEntry[]): Map<string, TopicEntry> {
  const map = new Map<string, TopicEntry>();
  for (const topic of topics) {
    const slug = createSlug(topic.name);
    if (!map.has(slug)) {
      map.set(slug, topic);
    }
  }
  return map;
}

/**
 * Route key -> index, built once for a given topics list. Lets callers get a
 * topic's position (for prev/next navigation) via `.get(routeKey)` instead of
 * `topics.indexOf(matchedTopic)` on every render.
 *
 * Duplicate-key safety: only the first index for a given route key is kept,
 * matching `.find()`'s first-match behavior.
 */
export function buildTopicIndexMap(topics: TopicEntry[]): Map<string, number> {
  const map = new Map<string, number>();
  topics.forEach((topic, index) => {
    const routeKey = getTopicRouteKey(topic);
    if (!map.has(routeKey)) {
      map.set(routeKey, index);
    }
  });
  return map;
}

export function resolveTopicFiles(folder: FolderItem): string[] {
  return [...(folder.files ?? []), ...(folder.folders?.flatMap(resolveTopicFiles) ?? [])];
}
