import categoryMeta from "#/category_meta";
import { COURSE_DATA } from "~/features/learning";
import { createRoute, createSlug } from "~/utils/slug";

import { PageShell } from "~/components/PageLayout/PageLayout";

import LearnPageClient from "./LearnPageClient";

export interface LearnCollection {
  title: string;
  slug: string;
  img: string;
  field: string;
  totalCourses: number;
  href: string;
}

export default function LearnPage() {
  const collections: LearnCollection[] = Object.entries(COURSE_DATA).map(([category, courses]) => ({
    title: category,
    slug: createSlug(category),
    img: categoryMeta[category as keyof typeof categoryMeta]?.img ?? "/og-image.png",
    field: categoryMeta[category as keyof typeof categoryMeta]?.field ?? "Learning",
    totalCourses: courses.length,
    href: createRoute("learn", category),
  }));

  return (
    <PageShell className="learn-page">
      <div className="app-container page-container">
        <LearnPageClient collections={collections} />
      </div>
    </PageShell>
  );
}
